<script setup lang="ts">import { reactive } from 'vue'; import { onShow } from '@dcloudio/uni-app'; import { blankResume } from '@/utils/resume'; import type { ResumeData } from '@/utils/resume'; const form=reactive<ResumeData>(blankResume()); onShow(()=>Object.assign(form,uni.getStorageSync('resume-draft')||{})); function chooseAvatar(){uni.chooseImage({count:1,sizeType:['compressed'],sourceType:['album','camera'],success:({tempFilePaths})=>{const path=tempFilePaths[0]; // #ifdef H5
uni.getFileSystemManager?void 0:null; // #endif
// H5 端转 base64 存储，避免 blob URL 刷新后失效
const fs=uni.getFileSystemManager?.bind(uni); if(!fs){const xhr=new XMLHttpRequest(); xhr.onload=()=>{const reader=new FileReader(); reader.onload=()=>{form.avatar=String(reader.result)}; reader.onerror=()=>{form.avatar=path}; reader.readAsDataURL(xhr.response); }; xhr.onerror=()=>{form.avatar=path}; xhr.open('GET',path); xhr.responseType='blob'; xhr.send(path); return }
form.avatar=path; uni.saveFile?.({tempFilePath:path,success:({savedFilePath})=>{form.avatar=savedFilePath}})}})} function removeAvatar(){form.avatar=''} const genderOptions=['男','女']; function onGenderChange(e:any){form.gender=genderOptions[Number(e.detail.value)]||''} function save(){uni.setStorageSync('resume-draft',form);uni.navigateBack()} function clear(){uni.showModal({title:'清空基本信息',content:'确定清空头像和全部基本信息吗？',success:({confirm})=>{if(!confirm)return;Object.assign(form,{avatar:'',name:'',gender:'',phone:'',email:'',intention:''});save()}})}</script>
<template><view class="page"><view class="card"><view class="avatar-row"><view v-if="form.avatar" class="avatar-wrap"><image :src="form.avatar" class="avatar" mode="aspectFill"/><text class="remove-avatar" @click="removeAvatar">删除头像</text></view><view v-else class="avatar-empty" @click="chooseAvatar">＋<text>上传头像</text></view><view class="avatar-action" @click="chooseAvatar">{{form.avatar?'重新选择':'选择照片'}}</view></view><text class="label">姓名</text><input v-model="form.name" class="input" placeholder="请输入姓名"/><text class="label">性别</text><picker class="picker" mode="selector" :range="genderOptions" @change="onGenderChange"><view class="picker-value" :class="{placeholder:!form.gender}">{{form.gender||'请选择性别'}}</view></picker><text class="label">联系电话</text><input v-model="form.phone" class="input" placeholder="请输入联系电话"/><text class="label">邮箱</text><input v-model="form.email" class="input" placeholder="请输入邮箱"/><text class="label">求职意向</text><input v-model="form.intention" class="input" placeholder="如：产品经理"/></view><button class="save" @click="save">完成</button><button class="delete-button" @click="clear">清空基本信息</button></view></template>
<style scoped lang="scss">.page{min-height:100vh;padding:18px 16px;background:#f5f6fa}.tip{padding:12px 14px;color:#64748b;font-size:13px;line-height:20px}.card{padding:18px 16px;background:#fff;border-radius:12px}.avatar-row{display:flex;align-items:center;margin-bottom:20px}.avatar-wrap{position:relative}.avatar{display:block;width:72px;height:72px;border-radius:8px}.remove-avatar{display:block;margin-top:5px;color:#ef4444;font-size:11px;text-align:center}.avatar-empty{display:flex;width:72px;height:72px;align-items:center;justify-content:center;flex-direction:column;border:1px dashed #93c5fd;border-radius:8px;color:#2563eb;font-size:24px}.avatar-empty text{font-size:11px}.avatar-action{margin-left:14px;color:#2563eb;font-size:13px}.label{display:block;margin:2px 0 8px;color:#344054;font-size:13px}.input{height:44px;box-sizing:border-box;margin-bottom:15px;padding:0 12px;border:1px solid #e2e8f0;border-radius:8px;background:#f8fafc;font-size:14px}.picker{margin-bottom:15px}.picker-value{height:44px;line-height:44px;padding:0 12px;border:1px solid #e2e8f0;border-radius:8px;background:#f8fafc;font-size:14px;color:#344054}.picker-value.placeholder{color:#98a2b3}.save,.delete-button{height:48px;margin-top:22px;border-radius:24px;line-height:48px}.save{background:#2563eb;color:#fff}.delete-button{border:1px solid #fecaca;background:#fff;color:#ef4444}</style>
